<?php

namespace Gmarineau\AdminPhp\Actions;

use Gmarineau\AdminPhp\Fields\Blocks;
use Gmarineau\AdminPhp\Models\Block;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;

/**
 * Makes the stored blocks of a zone match the submitted list: updates known blocks,
 * creates new ones (keeping the ULID generated by the editor) and deletes the others.
 */
class SyncBlocks
{
    /**
     * @param  array<int, array{id?: string|null, type: string, content?: array<string, mixed>|null}>  $items
     */
    public function handle(Model $model, Blocks $field, array $items): void
    {
        $existingBlocks = $this->zoneQuery($model, $field)->get()->keyBy('id');

        $keptBlockIds = [];

        foreach (array_values($items) as $position => $item) {
            $definition = $field->block($item['type']);

            $block = $existingBlocks->get($item['id'] ?? '') ?? $this->newBlock($model, $field, $item['id'] ?? null);

            $block->fill([
                'type' => $item['type'],
                'schema_version' => $definition->version(),
                'position' => $position,
                'content' => $definition->dehydrate($item['content'] ?? []),
            ])->save();

            $keptBlockIds[] = $block->id;
        }

        $this->zoneQuery($model, $field)->whereKeyNot($keptBlockIds)->delete();
    }

    /**
     * A submitted id is kept only if it is not already used elsewhere,
     * so a block can never be moved from another model by forging its id.
     */
    protected function newBlock(Model $model, Blocks $field, ?string $submittedId): Block
    {
        $block = new Block(['editor_name' => $field->name]);
        $block->blockable()->associate($model);

        if ($submittedId !== null && ! Block::query()->whereKey($submittedId)->exists()) {
            $block->id = $submittedId;
        }

        return $block;
    }

    /**
     * @return Builder<Block>
     */
    protected function zoneQuery(Model $model, Blocks $field): Builder
    {
        return Block::query()
            ->whereMorphedTo('blockable', $model)
            ->where('editor_name', $field->name)
            ->whereNull('parent_id');
    }
}
